UndeadFetter6(bool isEnemy)
		{
			if (GetFetterCount(CardFettersType.Undead, isEnemy) < 6)
			    return false;
			return IsUseNewFetter || UnityEngine.Random.Range(0, 100) < 10;
		}

UndeadFetter4_Revive(bool isEnemy)
		{
			return IsUseNewFetter && GetFetterCount(CardFettersType.Undead, isEnemy) >= 4 && UnityEngine.Random.Range(0, 100) < 10;
		}

