OrcsFetter2_MoveSpeed(float originalMoveSpeed, bool isEnemy)
		{
			if (IsUseNewFetter && GetFetterCount(CardFettersType.Orcs, isEnemy) >= 2)
			{
			    float bonus = originalMoveSpeed * 0.2f;
			    return bonus + originalMoveSpeed;
			}
			return originalMoveSpeed;
		}

OrcsFetter4_AttackSpeed(int currentHp, int maxHp, bool isEnemy)
		{
			if (!IsUseNewFetter)
			    return false;
			int fetterCount = GetFetterCount(CardFettersType.Orcs, isEnemy);
			return maxHp > 0 && fetterCount >= 4 && (float)currentHp / (float)maxHp < 0.5f;
		}

OrcsFetter6_BuildingDamage(int originalDamage, bool isEnemy, bool isBuilding)
		{
			if (IsUseNewFetter && isBuilding && GetFetterCount(CardFettersType.Orcs, isEnemy) >= 6)
			{
			    float bonus = (float)originalDamage * 0.75f;
			    return unchecked(originalDamage + (int)bonus);
			}
			return originalDamage;
		}

